SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "卢文进来降后，契丹以张希崇接任，守平州，遣三百骑监视。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：初，卢文进来降，契丹以籓汉都提举使张希崇代之为卢龙节度使，守平州，遣亲将以三百骑监之。；核对说明：卢来降为已录前事背景不重建；主卢龙节度、补新平州节度及旧平州任称并列，不改原字或现代地理。", "status": "draft", "id": "64c1daf8-e920-5444-b8f1-f2f003171146", "subject_id": "d9315b0f-fcc5-5519-bb22-8dc8d39a1274", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "初追叙卢文进南归后，张接任、派监确日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：初，卢文进来降，契丹以籓汉都提举使张希崇代之为卢龙节度使，守平州，遣亲将以三百骑监之。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "4a4d227a-3dea-558d-b4a4-6f57e531e173", "subject_id": "d9315b0f-fcc5-5519-bb22-8dc8d39a1274", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记张希崇：藩汉都提举使、接任卢龙节度守平州者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：初，卢文进来降，契丹以籓汉都提举使张希崇代之为卢龙节度使，守平州，遣亲将以三百骑监之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "8581ee8f-749f-5b12-bfba-553e9217fb3c", "subject_id": "dea611fa-916c-50fe-a044-c0c5fb5c23c6", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张希崇：藩汉都提举使、接任卢龙节度守平州者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：初，卢文进来降，契丹以籓汉都提举使张希崇代之为卢龙节度使，守平州，遣亲将以三百骑监之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "090f1d6c-3f05-51e0-ad6b-683db5de6468", "subject_id": "371101a6-1f35-578b-85c2-799efbd8d322", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记卢文进：其离去后职位获接替者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：初，卢文进来降，契丹以籓汉都提举使张希崇代之为卢龙节度使，守平州，遣亲将以三百骑监之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "9b266e3d-ea1f-580d-a498-f15fd616379f", "subject_id": "ead2e914-83dd-5f41-bf9a-5956fbd149ab", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "卢文进：其离去后职位获接替者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：初，卢文进来降，契丹以籓汉都提举使张希崇代之为卢龙节度使，守平州，遣亲将以三百骑监之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "8a0db70c-25be-51c1-9f9e-b4a7a439aaeb", "subject_id": "b88ee681-758b-582b-997e-76999c5cda87", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "description", "claim_text": "新张传称张希崇接卢文进为平州节度使，契丹派亲将三百骑监视。", "citation": "《新五代史》卷四十七，段落 xin-wudaishi-b08f244b9241-p001798；EPUB电子本，纸本及异文待核", "note": "原文：明宗時，盧文進自平州亡歸，契丹因以希崇代文進為平州節度使，遣其親將以三百騎監之。；核对说明：主卢龙节度守平州与新平州节度职称叙法并列，卢文进旧归降不重造；三百是监骑数不是所部总人口。", "status": "draft", "id": "3318ae21-4a2a-54d9-9139-e31eb6414840", "subject_id": "d9315b0f-fcc5-5519-bb22-8dc8d39a1274", "source_id": "c129098b-3add-59cf-8f65-2973bfab9325"}, {"subject_table": "person", "field_path": "description", "claim_text": "张希崇字德峰，幽州蓟县人，少通左氏春秋且好吟咏。", "citation": "《旧五代史》卷八十八，段落 jiu-wudaishi-205deb4a7860-p002093；EPUB电子本，纸本及异文待核", "note": "原文：張希崇，字德峰，幽州薊縣人也。父行簡，假薊州玉田令。希崇少通《左氏春秋》，復癖於吟詠。；核对说明：补字、史载籍贯与学识，不配现代出生坐标，不按后来卒龄倒生年。", "status": "draft", "id": "da851438-c256-57b6-b33d-3f830f884055", "subject_id": "dea611fa-916c-50fe-a044-c0c5fb5c23c6", "source_id": "31686701-00c9-5cc5-a9aa-d5f4cbfda131"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记张行简：希崇之父亲。", "citation": "《旧五代史》卷八十八，段落 jiu-wudaishi-205deb4a7860-p002093；EPUB电子本，纸本及异文待核", "note": "原文：張希崇，字德峰，幽州薊縣人也。父行簡，假薊州玉田令。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "dffce306-993b-5992-877e-f17bb55a8241", "subject_id": "69c29e1e-5497-582a-93ba-0ed286c2e85a", "source_id": "31686701-00c9-5cc5-a9aa-d5f4cbfda131"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "张行简是张希崇的父亲。", "citation": "《旧五代史》卷八十八，段落 jiu-wudaishi-205deb4a7860-p002093；EPUB电子本，纸本及异文待核", "note": "原文：張希崇，字德峰，幽州薊縣人也。父行簡，假薊州玉田令。；核对说明：张传明父行简，父子方向张行简→张希崇；假玉田令为史载职称不补任年月。", "status": "draft", "id": "ede9fd20-69ec-5455-892d-5efc3255c4b3", "subject_id": "66db5792-b495-5783-a702-121fc1519453", "source_id": "31686701-00c9-5cc5-a9aa-d5f4cbfda131"}, {"subject_table": "event", "field_path": "description", "claim_text": "张希崇本书生、幽州牙将，陷于契丹，性和易而渐获契丹将亲信。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：希崇本书生，为幽州牙将，没于契丹，性和易，契丹将稍亲信之，；核对说明：稍亲信是渐变背景，不当官将结义；没于契丹不是死亡。", "status": "draft", "id": "7a3b8f05-5511-55e2-acce-bed2b3703dd5", "subject_id": "0a03d378-b314-5c16-b857-21ed1420c43d", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "南归前生平与受信追叙，确年日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：希崇本书生，为幽州牙将，没于契丹，性和易，契丹将稍亲信之，；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "460b1403-bb6c-59dd-9039-03383424c0e1", "subject_id": "0a03d378-b314-5c16-b857-21ed1420c43d", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张希崇：旧牙将、被俘书生及渐获信任者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：希崇本书生，为幽州牙将，没于契丹，性和易，契丹将稍亲信之，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b0f517c3-c2d8-589b-961d-d4490ed78852", "subject_id": "8906ab40-ce00-5ec3-9877-757ba26ca73a", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "description", "claim_text": "张希崇与部曲谋南归，部曲愿归但忧敌众我寡。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：因与其部曲谋南归。部曲泣曰：“归固寝食所不忘也，然虏众我寡，奈何？”；核对说明：部曲无名不造角色名；担忧人数非确定己方兵少具体比率，谋归非已走。", "status": "draft", "id": "a6dc06f6-8784-59b0-88c8-2dd9a7912c03", "subject_id": "a308c0b6-c753-5671-bbf0-0a169ee64221", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "南归行动前谋议，确年日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：因与其部曲谋南归。部曲泣曰：“归固寝食所不忘也，然虏众我寡，奈何？”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "60029715-253c-5d20-bdf7-8125cfb9ff10", "subject_id": "a308c0b6-c753-5671-bbf0-0a169ee64221", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张希崇：召议南归者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：因与其部曲谋南归。部曲泣曰：“归固寝食所不忘也，然虏众我寡，奈何？”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f68351c7-02de-57b9-942c-35b8ad93b6ad", "subject_id": "c23dfea9-45ea-5cdd-a933-22f29c15bb03", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "description", "claim_text": "新张传称麾下怕不能全军脱身，劝张希崇独自离去。", "citation": "《新五代史》卷四十七，段落 xin-wudaishi-b08f244b9241-p001798；EPUB电子本，纸本及异文待核", "note": "原文：其麾下皆言兵多，不可俱亡，懼不得脫，因勸希崇獨去。；核对说明：独去为部下建议，后来举众南归不同，不把建议当已独逃结果。", "status": "draft", "id": "c0d74d2c-f0ba-5f59-8376-0cf227d43ff3", "subject_id": "a308c0b6-c753-5671-bbf0-0a169ee64221", "source_id": "c129098b-3add-59cf-8f65-2973bfab9325"}, {"subject_table": "event", "field_path": "description", "claim_text": "张希崇提出杀监将令其军溃散，并以距契丹王帐千余里争取时间。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：希崇曰：“吾诱其将杀之，兵必溃去。此去虏帐千馀里，比其知而征兵，吾属去远矣。”众曰：“善！”；核对说明：兵必溃与会征去远是张的预期，未先当战果；千余里史载概数不转地图精确公路距离。", "status": "draft", "id": "82815f0f-3da7-5fc8-aadf-1fd99419e137", "subject_id": "1c487e80-6fa8-5792-9b74-b250d50a055c", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "谋归会议中，确年日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：希崇曰：“吾诱其将杀之，兵必溃去。此去虏帐千馀里，比其知而征兵，吾属去远矣。”众曰：“善！”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "9a48f881-e6f8-55d4-abbd-3268f5423e13", "subject_id": "1c487e80-6fa8-5792-9b74-b250d50a055c", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张希崇：提出逃归计策者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：希崇曰：“吾诱其将杀之，兵必溃去。此去虏帐千馀里，比其知而征兵，吾属去远矣。”众曰：“善！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "51dca312-b6de-513f-84b8-8fc9523b6b85", "subject_id": "a612cf2a-c6d1-5402-b9c6-cb4f6c7743ef", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "description", "claim_text": "张希崇部先掘坑，填石灰。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：乃先为阱，实以石灰，；核对说明：准备与次日酒宴分别录，不编坑深、化学机理或具体参与者姓名。", "status": "draft", "id": "de8cac0d-5a4b-5ebe-82d1-e5f0dc62f2a8", "subject_id": "66c4f308-bc17-532a-b561-67dcb1a7eda6", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "杀监将前一日，确年日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：乃先为阱，实以石灰，；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "e2d419a4-72d6-5ffe-837d-36bd5de0b37f", "subject_id": "66c4f308-bc17-532a-b561-67dcb1a7eda6", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张希崇：计策部署者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：乃先为阱，实以石灰，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "51219dcc-f4ad-5b84-9d3f-5135d9020af9", "subject_id": "1d476602-d627-5794-9412-d47b57788c14", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "description", "claim_text": "次日张希崇召契丹将饮酒，醉后杀将及从者，投入坑中。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：明日，召虏将饮，醉，并从者杀之，投诸阱中。；核对说明：明日为相对掘坑日；主杀后投与旧悉投灰阱中毙叙法分别保留，不虚构监将姓名或杀伤人数。", "status": "draft", "id": "3e894534-7dcb-544f-811b-0c303b9a6dd8", "subject_id": "a43a6a5b-f052-52c1-9b2a-f090cc910e3e", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "填灰坑次日，确年日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：明日，召虏将饮，醉，并从者杀之，投诸阱中。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "2064e435-98d7-50c7-89e4-0dbdaea14a70", "subject_id": "a43a6a5b-f052-52c1-9b2a-f090cc910e3e", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张希崇：召饮与杀监将计策执行者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：明日，召虏将饮，醉，并从者杀之，投诸阱中。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "e0a51515-ee24-5ce5-996f-db8d40969377", "subject_id": "d13aa119-3ce3-5b50-9747-95f67155073f", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧张传称首领与群从来牙帐，饮醉后悉投灰坑中毙。", "citation": "《旧五代史》卷八十八，段落 jiu-wudaishi-205deb4a7860-p002093；EPUB电子本，纸本及异文待核", "note": "原文：明旦，首領與群從至，希崇飲以醇酎數鐘，既醉，悉投於灰阱中斃焉。；核对说明：主杀后投、旧投灰阱中毙的动作次序不同保留，不据此推现代确定死因。", "status": "draft", "id": "5292ca45-804e-5f4c-ae16-16e977bbba61", "subject_id": "a43a6a5b-f052-52c1-9b2a-f090cc910e3e", "source_id": "31686701-00c9-5cc5-a9aa-d5f4cbfda131"}, {"subject_table": "event", "field_path": "description", "claim_text": "张希崇部迅速攻城北契丹营，契丹军溃去。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：其营在城北，亟发兵攻之，契丹众皆溃去。；核对说明：溃去为散逃，非全部歼灭；城北营并非整个契丹国都。", "status": "draft", "id": "5eb11cb7-26bc-5dcc-a8eb-e6c0b70fd954", "subject_id": "d2730667-47fc-5278-9091-0a423c680aa6", "source_id": "a7869c5a-bbc6-5bd9-a4df-e224302122c0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "监将被杀后，确年日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p033·原文件第65行", "note": "原文：其营在城北，亟发兵攻之，契丹众皆溃去。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "38a360aa-0884-59e5-9b60-8613314ed3c6", "